-- DATA LOAD GUIDE
-- The CSV should be the cleaned file generated by the Python pipeline:
-- data/cleaned/dataco_supply_chain_cleaned.csv
--
-- Option A: MySQL Workbench Table Data Import Wizard
--   1. Run 01_schema.sql.
--   2. Open Table Data Import Wizard.
--   3. Select dataco_supply_chain.supply_chain_orders.
--   4. Select the cleaned CSV.
--   5. Confirm column mapping.
--
-- Option B: LOAD DATA LOCAL INFILE
-- Make sure LOCAL INFILE is enabled in your MySQL client/server.
--
-- Example:
-- LOAD DATA LOCAL INFILE 'C:/path/to/dataco_supply_chain_cleaned.csv'
-- INTO TABLE supply_chain_orders
-- FIELDS TERMINATED BY ','
-- ENCLOSED BY '"'
-- LINES TERMINATED BY '\n'
-- IGNORE 1 ROWS
-- (
--   Order_ID, Order_Item_ID, Order_Date, Shipping_Date, Transaction_Type,
--   Order_Status, Delivery_Status, Shipping_Mode, Market, Order_Region,
--   Order_Country, Order_State, Order_City, Customer_ID, Customer_Segment,
--   Category_ID, Category_Name, Department_ID, Department_Name, Product_Card_ID,
--   Product_Name, Product_Price, Order_Item_Product_Price, Order_Item_Quantity,
--   Order_Item_Discount, Order_Item_Discount_Rate, Sales, Order_Item_Total,
--   Order_Profit_Per_Order, Order_Item_Profit_Ratio, Actual_Shipping_Days,
--   Scheduled_Shipping_Days, Shipping_Delay_Days, Late_Delivery_Risk,
--   On_Time_Flag, Late_Flag, Order_Month, Quarter
-- );
